# The orrery's export and its SHA, exactly as tools/pull_constants_export.py
# writes them from orrery b61d1982. The config above is what the mirror
# writes from THIS export, so the two travel together: if the maintenance
# run's pull cannot reach GitHub, the mirror still reads the export the
# config was made from, instead of an older one it would write backwards
# from. Each is replaced only if it is still the copy pulled at 95b394f8.
REPLACED = [('data/constants_export.json', '978aef9e65733a9f66cf237abb415e91', '', 'b848587fdfd3630d79d6c2820b728e93'), ('data/constants_export.sha', '5a3550c34d5df0774b38ca3955b54978', 'eNoFwckBACAIA7C/01jxwHGo0P1HMOFG4vpA71er8sFNlTPikKJDGnjG9gHv/wux', 'fba6df184fa70827856cb818da3d0ab4')]

FIXTURE = "documentation/fixture_hovers_L345_on_2df02f3b.json"
FIXTURE_B64 = ''
FIXTURE_MD5 = "0f792b79560bedc34c36ea37bd92f281"

NEXT_STEPS = """
NEXT STEPS, in this order (a config change is not deployed until the
cache is rebuilt):

  1. (do) Run the cache builder by hand, as you do each night. It copies
     the new config into the served cache.
  2. (do) Run python gallery_maintenance_run.py. Expect 19 of 19 gating
     checkers passing. "Constants export pull" brings the orrery's
     export at b61d1982, which this patch already wrote, so it and
     "Config mirror" should both say no change.
     "Display figures" should end "57 hover(s) ... 13 graded, 7 graded
     by line, 44 held to the fixture", and list 1 served AU printed in
     full: Earth: Inner Core.
  3. (do) Commit the config, the cache and the rest together, and push.
  4. (do) On your phone, close the tab and reopen the Earth room, then
     the Sun room. Check each line in the orrery's
     documentation/PREBUILD_L345_gallery_hover_changes_20260928.md, plus
     the crust's new sentence and the inner core's 0.000008165 AU.
  5. (do) In the ORRERY folder, run the orrery maintenance run.
     "Exact rows by the count" should now PASS: 20 of 20.
  6. (do) Move this script, and the unrun patch 4, into documentation/.
  7. Tell Claude the new gallery SHA. Orrery patch D20 is next.
"""


def fingerprint(data):
    return hashlib.md5(data.replace(b"\r\n", b"\n")).hexdigest()


def fail(msg):
    print("FAILURE: " + msg)
    print("NOTHING was written. Undo is not needed.")
    sys.exit(1)


def main():
    if os.path.basename(os.getcwd()) == "documentation" or \
            os.path.basename(HERE) == "documentation":
        fail("this is running from documentation/. Run it from the gallery "
             "repo root, then file it in documentation/.")
    if not os.path.exists(os.path.join(HERE, "interactive.html")):
        fail("interactive.html is not beside this script. Save it in the "
             "GALLERY repo root, not the orrery.")
    results = []
    for rel, fp, edits in TARGETS:
        path = os.path.join(HERE, rel)
        if not os.path.exists(path):
            fail("%s not found" % rel)
        with open(path, "rb") as handle:
            raw = handle.read()
        got = fingerprint(raw)
        if got != fp:
            fail("%s is not the file this patch was built on (fingerprint "
                 "%s, expected %s). Pull or discard local changes first."
                 % (rel, got, fp))
        crlf = b"\r\n" in raw
        text = raw.replace(b"\r\n", b"\n").decode("utf-8")
        for label, old, new in edits:
            n = text.count(old)
            if n != 1:
                fail('%s: "%s" -- expected 1 match, got %d' % (rel, label, n))
            text = text.replace(old, new)
        print("ok    %s: %d edit(s)" % (rel, len(edits)))
        data = text.encode("utf-8")
        try:
            data.decode("ascii")
        except UnicodeDecodeError as exc:
            fail("%s would not be ASCII after the patch (%s)" % (rel, exc))
        if crlf:
            data = data.replace(b"\n", b"\r\n")
        results.append((path, data))
    for rel, fp, blob, md5 in REPLACED:
        path = os.path.join(HERE, rel)
        if not os.path.exists(path):
            fail("%s not found" % rel)
        with open(path, "rb") as handle:
            got = fingerprint(handle.read())
        data = zlib.decompress(base64.b64decode(blob))
        if hashlib.md5(data).hexdigest() != md5:
            fail("the embedded copy of %s does not match its checksum" % rel)
        if got == hashlib.md5(data).hexdigest():
            print("ok    %s: already the copy from b61d1982" % rel)
            continue
        if got != fp:
            fail("%s is neither the copy pulled at 95b394f8 nor the one at "
                 "b61d1982 (fingerprint %s). Pull or discard local changes "
                 "first." % (rel, got))
        print("ok    %s: replaced with the copy from b61d1982" % rel)
        results.append((path, data))
    fixture = zlib.decompress(base64.b64decode(FIXTURE_B64))
    if hashlib.md5(fixture).hexdigest() != FIXTURE_MD5:
        fail("the embedded fixture does not match its checksum")
    fixture_path = os.path.join(HERE, FIXTURE)
    if os.path.exists(fixture_path):
        with open(fixture_path, "rb") as handle:
            if handle.read().replace(b"\r\n", b"\n") != fixture:
                fail("%s already exists and differs" % FIXTURE)
        write_fixture = False
        print("ok    %s: already filed, identical" % FIXTURE)
    else:
        write_fixture = True
        print("ok    %s: new, %d bytes" % (FIXTURE, len(fixture)))
    for path, data in results:
        with open(path, "wb") as handle:
            handle.write(data)
    if write_fixture:
        with open(fixture_path, "wb") as handle:
            handle.write(fixture)
    print("stamp gallery/feature_renderers.js, tools/mirror_constants.py, "
          "tools/test_mirror_constants.py, documentation/"
          "smoke_display_figures.js: updated September 28, 2026 (L-345)")
    print("PATCH APPLIED: %d file(s) written, %d new."
          % (len(results), 1 if write_fixture else 0))
    print(NEXT_STEPS)


if __name__ == "__main__":
    main()
